text = "1 2 3 4 5"                                                                                                             
                                                                                                                                 
lst = text.split(" ")   # 문자열 → 리스트                                                                                      
print(lst)              # ['1', '2', '3', '4', '5']                                                                            
                                                                                                                                 
result = " ".join(lst)  # 리스트 → 문자열                                                                                      
print(result)           # 1 2 3 4 5 